use kassiber_pydecimal::{Decimal, MAX_FIXED_PADDING};
#[inline(never)]
fn prior(d: &Decimal) -> bool {
    let padding = if d.exponent() >= 0 {
        if d.is_zero() { 0 } else { i128::from(d.exponent()) }
    } else { (-i128::from(d.adjusted()) - 1).max(0) };
    padding <= i128::from(MAX_FIXED_PADDING)
}
#[inline(never)]
fn candidate(d: &Decimal) -> bool {
    if (-i128::from(MAX_FIXED_PADDING) - 1..=0).contains(&i128::from(d.exponent())) { return true; }
    prior(d)
}
fn main() {
    let args:Vec<_> = std::env::args().collect();
    let d:Decimal = format!("{}E-32", "1234567890".repeat(args[2].parse().unwrap())).parse().unwrap();
    let f=if args[1]=="prior" { prior } else { candidate };
    for _ in 0..2_000_000 { std::hint::black_box(f(std::hint::black_box(&d))); }
}
